#include <bits/stdc++.h>
using namespace std; using U=uint64_t;
int main(int argc,char**argv){ifstream f(argv[1]);int n,m;f>>n>>m;U adj[57]={},C=0,I=0,E=0;vector<pair<int,int>> edges;for(int a,b;f>>a>>b;){adj[a]|=1ULL<<b;adj[b]|=1ULL<<a;edges.push_back({a,b});}for(int v=0;v<n;v++)if(__builtin_popcountll(adj[v])==7)C|=1ULL<<v;for(int v=0;v<n;v++)if(!(C>>v&1)&&!(adj[v]&C))I|=1ULL<<v;E=((1ULL<<57)-1)^C^I;vector<array<int,3>>t;for(auto[a,b]:edges)if((I>>a&1)&&(I>>b&1))for(int c=b+1;c<n;c++)if((I>>c&1)&&(adj[a]>>c&1)&&(adj[b]>>c&1))t.push_back({a,b,c});long long families=0,patterns=0,tested=0,survivors=0;int best=0;array<int,8>sel;int d[57]={};U del[57]={};
function<void(int,int)>choose=[&](int k,int start){if(k<8){for(int a=start;a<=14-(8-k);a++){sel[k]=a;choose(k+1,a+1);}return;}U covered=0;for(int z:sel)for(int v:t[z])covered|=1ULL<<v;if(__builtin_popcountll(covered)!=20)return;families++;int missing=__builtin_ctzll(I&~covered);vector<pair<int,int>>ee;for(auto[a,b]:edges)if((E>>a&1)&&(E>>b&1)&&(adj[a]>>missing&1)&&(adj[b]>>missing&1))ee.push_back({a,b});assert(ee.size()==2);
function<void(int)>pick=[&](int q){if(q<8){auto tr=t[sel[q]];for(int omit=0;omit<3;omit++){int a=tr[(omit+1)%3],b=tr[(omit+2)%3];d[a]++;d[b]++;del[a]|=1ULL<<b;del[b]|=1ULL<<a;pick(q+1);del[a]^=1ULL<<b;del[b]^=1ULL<<a;d[a]--;d[b]--;}return;}patterns++;vector<int>one,two;for(int v=0;v<57;v++)if(d[v]==1)one.push_back(v);else if(d[v]==2)two.push_back(v);if(two.size()<3)return;
for(auto[e1,e2]:ee)for(int j=5;j<=6;j++)for(int s2=j-2;s2<=min(j,(int)two.size());s2++){int s1=j-s2;function<void(int,int,U)>p1;function<void(int,int,U)>p2;p1=[&](int pos,int left,U cover){if(!left){tested++;int bound=__builtin_popcountll(cover)+s2-(j-2);best=max(best,bound);if(bound>=21){survivors++;if(survivors<=1){cout<<"FIRST_PASS j="<<j<<" s2="<<s2<<" bound="<<bound<<" ee="<<e1<<","<<e2<<"\n";}}return;}for(int x=pos;x<=(int)one.size()-left;x++){int v=one[x];p1(x+1,left-1,cover|((adj[v]&~del[v])&I)|(1ULL<<v));}};p2=[&](int pos,int left,U cover){if(!left){p1(0,s1,cover);return;}for(int x=pos;x<=(int)two.size()-left;x++){int v=two[x];p2(x+1,left-1,cover|((adj[v]&~del[v])&I)|(1ULL<<v));}};p2(0,s2,(adj[e1]|adj[e2])&I);}
};pick(0);};choose(0,0);cout<<"families="<<families<<" deletion_patterns="<<patterns<<" S_sets="<<tested<<" max_I_upper="<<best<<" survivors="<<survivors<<"\n";}
